import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long m = Long.parseLong(next());
        long[] d = new long[(int) m];
        for (int i = 0; i < d.length; i++) d[i] = Long.parseLong(next());

        int n = (int) m - 1;
        long[][] cost = new long[n][n];
        for (int length = 2; length <= n; length++) {
            for (int i = 0; i + length - 1 < n; i++) {
                int j = i + length - 1;
                long best = Long.MAX_VALUE;
                for (int k = i; k < j; k++) {
                    best = Math.min(best, cost[i][k] + cost[k + 1][j] + d[i] * d[k + 1] * d[j + 1]);
                }
                cost[i][j] = best;
            }
        }
        System.out.println(cost[0][n - 1]);
    }
}
